import openpyxl
wb=openpyxl.load_workbook('Queue/2025-07-14_Active_Queue_Report.xlsx',data_only=True)
ws=wb['Active Queue']
from collections import Counter
feeds=Counter()
for r in ws.iter_rows(min_row=2,values_only=True):
    feeds[str(r[4])]+=1
for f,c in feeds.items():
    if '108' in f: print(repr(f),c)
print('rows',ws.max_row-1)
# print all with queue date after 2024-05-15 on 108
